package routes

import (
	"encoding/json"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"

	appconfig "github.com/suprimkhatri77/cartspace/backend/internal/config"
	"github.com/suprimkhatri77/cartspace/backend/internal/routes/config"
)

// The committed OpenAPI spec (generated by packages/openapi) must describe
// exactly the routes and codes the API has, so the generated client can't
// drift from the server. Regenerate with `bun run generate`.

const specPath = "../../openapi.json"

// undocumented are served but intentionally not part of the API contract.
var undocumented = []string{
	"GET /",
	"GET /docs",
	"GET /api/v1/docs",
	"GET /api/v1/docs/",
	"GET /api/v1/openapi.json",
}

type spec struct {
	Paths      map[string]map[string]json.RawMessage `json:"paths"`
	Components struct {
		Schemas map[string]struct {
			Enum []string `json:"enum"`
		} `json:"schemas"`
	} `json:"components"`
}

func loadSpec(t *testing.T) spec {
	t.Helper()
	raw, err := os.ReadFile(specPath)
	if err != nil {
		t.Fatalf("read %s (run bun run generate): %v", specPath, err)
	}
	var s spec
	if err := json.Unmarshal(raw, &s); err != nil {
		t.Fatalf("parse %s: %v", specPath, err)
	}
	return s
}

var ginParam = regexp.MustCompile(`:(\w+)`)

func TestSpecMatchesRoutes(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	Setup(r, config.Config{Config: &appconfig.Config{}})

	served := map[string]bool{}
	for _, route := range r.Routes() {
		key := route.Method + " " + ginParam.ReplaceAllString(route.Path, "{$1}")
		if !slices.Contains(undocumented, route.Method+" "+route.Path) {
			served[key] = true
		}
	}

	documented := map[string]bool{}
	for path, ops := range loadSpec(t).Paths {
		for method := range ops {
			documented[strings.ToUpper(method)+" "+path] = true
		}
	}

	for key := range served {
		if !documented[key] {
			t.Errorf("route %s is not in openapi.json; document it in packages/openapi", key)
		}
	}
	for key := range documented {
		if !served[key] {
			t.Errorf("openapi.json documents %s, which the API does not serve", key)
		}
	}
}

func TestSpecCodesMatchConstants(t *testing.T) {
	s := loadSpec(t)

	for schema, file := range map[string]string{
		"ErrorCode":      "error_codes.go",
		"ValidationCode": "validation_codes.go",
	} {
		goCodes := stringConstants(t, filepath.Join("..", "constants", file))
		specCodes := slices.Clone(s.Components.Schemas[schema].Enum)
		slices.Sort(goCodes)
		slices.Sort(specCodes)
		if !slices.Equal(goCodes, specCodes) {
			t.Errorf("%s enum in openapi.json differs from constants/%s\n spec: %v\n   go: %v\nupdate packages/types and run bun run generate",
				schema, file, specCodes, goCodes)
		}
	}
}

// stringConstants returns the values of the string constants (const
// declarations only) in a Go file.
func stringConstants(t *testing.T, path string) []string {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), path, nil, 0)
	if err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}

	var values []string
	for _, decl := range f.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.CONST {
			continue
		}
		for _, spec := range gen.Specs {
			for _, value := range spec.(*ast.ValueSpec).Values {
				lit, ok := value.(*ast.BasicLit)
				if !ok || lit.Kind != token.STRING {
					continue
				}
				if v, err := strconv.Unquote(lit.Value); err == nil {
					values = append(values, v)
				}
			}
		}
	}
	if len(values) == 0 {
		t.Fatalf("no string constants in %s", path)
	}
	return values
}
